#include <iostream>
#include <cmath>

// Giai phuong trinh bac hai dung tham chieu C++
int solveQuadratic(double a, double b, double c, double &x1, double &x2) {
    double delta = b * b - 4 * a * c;
    if (delta < 0) {
        return 0;
    } else if (delta == 0) {
        x1 = -b / (2 * a);
        x2 = x1;
        return 1;
    } else {
        x1 = (-b + std::sqrt(delta)) / (2 * a);
        x2 = (-b - std::sqrt(delta)) / (2 * a);
        return 2;
    }
}

void swapRef(int &x, int &y) {
    int temp = x;
    x = y;
    y = temp;
}

int main() {
    double a = 1.0, b = -5.0, c = 6.0;
    double r1 = 0.0, r2 = 0.0;
    int numRoots = solveQuadratic(a, b, c, r1, r2);

    std::cout << "Roots count: " << numRoots << "\n";
    std::cout << "x1 = " << r1 << ", x2 = " << r2 << "\n";

    int val1 = 5, val2 = 3;
    swapRef(val1, val2);
    std::cout << "Swapped: " << val1 << " " << val2 << "\n";
    return 0;
}

#include <iostream>

// 1D Array via pointer notation
void print1D(const int *p, int n) {
    for (int i = 0; i < n; ++i) {
        std::cout << *(p + i) << (i + 1 == n ? "\n" : " ");
    }
}

// 2D Array via fixed columns
void print2DFixed(const int x[][3], int rows) {
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < 3; ++j) {
            std::cout << x[i][j] << " ";
        }
        std::cout << "\n";
    }
}

// 2D Array via flattened pointer: k = i * cols + j
void print2DFlattened(const int *p, int rows, int cols) {
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            std::cout << *(p + i * cols + j) << " ";
        }
        std::cout << "\n";
    }
}

int main() {
    int arr1D[5] = {10, 20, 30, 40, 50};
    std::cout << "1D Array (first 3 elements):\n";
    print1D(arr1D, 3);

    int arr2D[2][3] = {
        {1, 2, 3},
        {4, 5, 6}
    };

    std::cout << "2D Array (Fixed Column [][3]):\n";
    print2DFixed(arr2D, 2);

    std::cout << "2D Array (Flattened Pointer):\n";
    print2DFlattened(&arr2D[0][0], 2, 3);
    return 0;
}
